SELECT CASE WHEN d.budget >= 3168000 THEN 'high' WHEN d.budget >= 1592000 THEN 'mid' ELSE 'low' END AS budget_bucket, CASE WHEN d.location IN ('Chiang Mai', 'London') THEN 'tier_1' ELSE 'other' END AS location_group, COUNT(DISTINCT e.salary) AS unique_depts FROM employees e FULL OUTER JOIN departments d ON d.id = e.dept_id WHERE UPPER(TRIM(e.email)) = 'FRANK@COMPANY.CO' GROUP BY CASE WHEN d.budget >= 3168000 THEN 'high' WHEN d.budget >= 1592000 THEN 'mid' ELSE 'low' END, CASE WHEN d.location IN ('Chiang Mai', 'London') THEN 'tier_1' ELSE 'other' END HAVING COUNT(DISTINCT e.salary) >= 4 ORDER BY unique_depts DESC;
